// HTML ya escapado en Apps Script: mismo blindaje que v6, sin escapar dos veces.
const norm = (s) => String(s ?? '').replace(/&(?!(amp|lt|gt|quot|#\d+);)/g, '&amp;').replace(/<(?!\/?(b|i|u|s|code|pre)>|a href="[^"]*">|\/a>)/g, '&lt;') || '(sin texto)';
const r = $input.first().json;
const canal = r.canal || 'telegram';
// Solo true booleano o su representación textual activan sinCopia.
const sinCopia = r.sinCopia === true || r.sinCopia === 'true';
if (!['telegram', 'whatsapp'].includes(canal)) throw new Error('Canal inválido');
const destino = String(r.destino ?? '').trim();
if (!destino || (canal === 'whatsapp' && !/^\d+$/.test(destino))) throw new Error('Destino inválido');
const botones = r.botones == null ? [] : r.botones;
if (!Array.isArray(botones) || botones.some(b => !b || typeof b.text !== 'string' || !b.text.trim() || typeof b.callback_data !== 'string' || !b.callback_data || Buffer.byteLength(b.callback_data) > 64)) throw new Error('Botones inválidos');
const editar = r.editarMessageId == null || r.editarMessageId === '' ? null : Number(r.editarMessageId);
if (editar !== null && (!Number.isSafeInteger(editar) || editar <= 0)) throw new Error('editarMessageId debe ser el ID numérico de Telegram (restauración WA: T-048)');
return [{ json: { ...r, canal, sinCopia, destino, texto: norm(r.texto), botones, editarMessageId: editar, waOk: true, wamid: null, messageId: null, telegramOk: true }, pairedItem: { item: 0 } }];

function aWhatsApp(html) {
  return String(html)
    .replace(/<\/?(b|strong)>/g, '*').replace(/<\/?(i|em)>/g, '_').replace(/<\/?(s|del)>/g, '~')
    .replace(/<\/?(code|pre)>/g, '```').replace(/<a href="([^"]+)">([^<]*)<\/a>/g, '$2: $1')
    .replace(/<[^>]+>/g, '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
}
// T-048: guardar texto plano del original, sin cabecera de la copia ni marcas de WhatsApp.
const r = $input.first().json;
const texto = aWhatsApp(r.texto);
const textoContexto = String(r.texto).replace(/<a href="([^"]+)">([^<]*)<\/a>/g, '$2: $1')
  .replace(/<[^>]+>/g, '').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&#(\d+);/g, (m, n) => Number(n) <= 0x10ffff ? String.fromCodePoint(Number(n)) : m)
  .replace(/&amp;/g, '&').slice(0, 1000);
const chars = s => Array.from(s);
const base = { messaging_product: 'whatsapp', recipient_type: 'individual', to: r.destino };
if (r.replyTo) base.context = { message_id: String(r.replyTo) };
const colaWA = [];
const agregarTexto = s => { const c = chars(s); for (let i = 0; i < c.length; i += 4096) colaWA.push({ ...base, type: 'text', text: { body: c.slice(i, i + 4096).join('') } }); };
// No descartar opciones ni cambiar callback_data. Más de 10 es un error visible en la copia.
if (r.botones.length > 10) return [{ json: { ...r, textoContexto, waEnviados: [], colaWA, waPos: 0, waOk: false }, pairedItem: { item: 0 } }];
if (!r.botones.length) agregarTexto(texto);
else {
  const corto = chars(texto).length <= 1024;
  if (!corto) agregarTexto(texto);
  const limite = r.botones.length <= 3 ? 20 : 24;
  const usados = new Set();
  const titulo = (s, i) => {
    s = aWhatsApp(s).replace(/\s+/g, ' ').trim() || 'Opción ' + (i + 1);
    let t = chars(s).slice(0, limite).join('');
    if (chars(s).length > limite) {
      const p = t.lastIndexOf(' ');
      t = (p >= limite / 2 ? t.slice(0, p) : chars(t).slice(0, limite - 1).join('')) + '…';
    }
    if (usados.has(t)) { const suf = ' ' + (i + 1); t = chars(t).slice(0, limite - suf.length).join('') + suf; }
    usados.add(t); return t;
  };
  const interactive = { type: r.botones.length <= 3 ? 'button' : 'list', body: { text: corto ? texto : 'Seleccione una opción para el mensaje anterior.' } };
  if (r.botones.length <= 3) interactive.action = { buttons: r.botones.map((b, i) => ({ type: 'reply', reply: { id: b.callback_data, title: titulo(b.text, i) } })) };
  else interactive.action = { button: 'Ver opciones', sections: [{ title: 'Opciones', rows: r.botones.map((b, i) => ({ id: b.callback_data, title: titulo(b.text, i) })) }] };
  colaWA.push({ ...base, type: 'interactive', interactive });
}
return [{ json: { ...r, textoContexto, waEnviados: [], colaWA, waPos: 0 }, pairedItem: { item: 0 } }];

const r = $('Siguiente WhatsApp').itemMatching(0).json;
const j = $input.first().json;
const id = !j.error && typeof j.messages?.[0]?.id === 'string' && j.messages[0].id;
// Conservar TODOS los wamids aceptados, incluso si falla otra parte del envío.
// Un fragmento de texto no ofrece botones: no aceptar callbacks sobre ese wamid.
const waEnviados = [...(r.waEnviados || [])];
if (id && !waEnviados.some(e => e.wamid === id)) {
  const q = r.solicitudWA?.interactive;
  const botones = q?.type === 'button' ? q.action.buttons.map(b => b.reply.id)
    : q?.type === 'list' ? q.action.sections.flatMap(s => s.rows.map(b => b.id)) : [];
  waEnviados.push({ wamid: id, botones, ts: new Date().toISOString() });
}
// No propagar cuerpos de error del proveedor.
return [{ json: { ...r, waEnviados, waOk: r.waOk && !!id, wamid: id || r.wamid, waPos: r.waPos + 1 }, pairedItem: { item: 0 } }];

const r = $input.first().json;
// T-052: cola vacía evita tanto envío/edición como aviso de fallo Meta al grupo.
if (r.sinCopia === true) return [{ json: { ...r, colaTG: [], tgPos: 0, avisoTG: false }, pairedItem: { item: 0 } }];
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cabecera = '<b>🤖 Bot → ' + esc(r.nombre || 'Usuario') + ' (' + esc(r.destino) + ')</b>\n';
const opciones = r.botones.length ? '\n\nOpciones: ' + r.botones.map(b => esc(b.text)).join(' · ') : '';
const texto = (r.waOk ? '' : '⚠️ No se pudo entregar por WhatsApp\n') + r.texto + opciones;
// Copia completa, incluso con texto WA largo. Se cierran/reabren etiquetas al dividir;
// el límite conservador cuenta caracteres del HTML, además de reservar la cabecera.
function dividirHTML(s, limite) {
  const out = [], stack = []; let parte = '';
  const cierres = () => stack.slice().reverse().map(t => '</' + t.nombre + '>').join('');
  const aperturas = () => stack.map(t => t.token).join('');
  for (const token of s.match(/<[^>]+>|&(?:amp|lt|gt|quot|#\d+);|[\s\S]/gu) || []) {
    if (parte.length + token.length + cierres().length + 16 > limite) {
      out.push(parte + cierres()); parte = aperturas();
    }
    if (token.length > limite / 2) throw new Error('Etiqueta HTML excesiva');
    parte += token;
    const ini = /^<(b|i|u|s|code|pre|a)(?:\s[^>]*)?>$/.exec(token);
    const fin = /^<\/(b|i|u|s|code|pre|a)>$/.exec(token);
    if (ini) stack.push({ nombre: ini[1], token });
    if (fin && stack.length && stack[stack.length - 1].nombre === fin[1]) stack.pop();
  }
  if (parte) out.push(parte + cierres());
  return out;
}
const cab = cabecera;
const colaTG = dividirHTML(texto, 3900 - cab.length).map((p, i) => ({ chatId: r.grupoTelegram, texto: cab + p, editarMessageId: i === 0 ? r.editarMessageId : null, replyTo: null, botones: [] }));
return [{ json: { ...r, colaTG, tgPos: 0, avisoTG: false }, pairedItem: { item: 0 } }];

const r = $input.first().json;
// Lista plana: los Switch eligen teclados fixedCollection estáticos como en v6.
const colaTG = [{ chatId: r.destino, texto: r.texto, editarMessageId: r.editarMessageId, replyTo: r.replyTo || null, botones: r.botones.map(b => ({ ...b })) }];
// El texto contiene &amp; / &lt; / &gt; desde Preparar envío (HTML ya escapado).
return [{ json: { ...r, colaTG, tgPos: 0, avisoTG: false }, pairedItem: { item: 0 } }];

const r = $input.first().json;
const s = r.colaTG[r.tgPos];
// &amp;: texto HTML preparado aguas arriba, no volver a escapar etiquetas intencionales.
return [{ json: { ...r, solicitudTG: s, texto: s.texto }, pairedItem: { item: 0 } }];

const r = $('Siguiente Telegram').itemMatching(0).json;
const j = $input.first().json;
const id = !j.error && (j.result?.message_id || j.message_id);
// Un reintento de edición idéntica devuelve 400: el estado deseado ya existe.
// Se reconoce solo ese error concreto; ningún otro fallo se trata como éxito.
const sinCambios = !!r.solicitudTG.editarMessageId && /message is not modified/i.test(String(j.error?.message || j.error?.description || j.error || j.message || j.description || ''));
const mensaje = id || (sinCambios ? r.solicitudTG.editarMessageId : null);
return [{ json: { ...r, telegramOk: r.telegramOk && !!mensaje, messageId: r.avisoTG ? r.messageId : (r.messageId || mensaje || null), tgPos: r.tgPos + 1 }, pairedItem: { item: 0 } }];

const r = $input.first().json;
// Mensaje fijo: no filtrar errores HTTP ni secretos al grupo. &amp; para texto HTML seguro.
const colaTG = [{ chatId: r.grupoTelegram, texto: '⚠️ Falló el envío o la copia del bot de cuentas. Revise la ejecución en n8n.', editarMessageId: null, replyTo: null, botones: [] }];
return [{ json: { ...r, colaTG, tgPos: 0, avisoTG: true }, pairedItem: { item: 0 } }];

const r = $input.first().json;
const esWA = r.canal === 'whatsapp';
const copiaOk = esWA && r.sinCopia !== true ? r.telegramOk === true : null;
return [{ json: {
  ok: esWA ? r.waOk === true : r.telegramOk === true,
  canal: r.canal,
  messageId: esWA && copiaOk !== true ? null : (r.messageId || null),
  wamid: esWA ? (r.wamid || null) : null,
  copiaOk
}, pairedItem: { item: 0 } }];

const r = $input.first().json;
const enviados = r.canal === 'whatsapp' ? (r.waEnviados || []) : [];
const destino = String(r.destino || '').replace(/\D/g, '');
// T-052: el contexto existe aunque no haya copia; solo vincular una copia completa.
const conCopia = !r.sinCopia && r.telegramOk === true && Number.isSafeInteger(r.messageId) && r.messageId > 0;
const contextosWA = destino ? enviados.map(e => ({ wamid: e.wamid, datos: JSON.stringify({
  destino, texto: String(r.textoContexto || '').slice(0, 1000), botones: e.botones,
  ...(conCopia ? { tgMessageId: r.messageId } : {}), ts: e.ts
}) })) : [];
return [{ json: { ...r, contextosWA, contextoPos: 0, contextoError: enviados.length > 0 && !destino }, pairedItem: { item: 0 } }];

const r = $('Siguiente contexto WA').itemMatching(0).json;
const j = $input.first().json;
return [{ json: { ...r, contextoPos: r.contextoPos + 1, contextoError: r.contextoError || !!j.error || !j.id }, pairedItem: { item: 0 } }];
